@kt.kernel
def k(
    a=kt.In(64, 64, dtype="mx7a", layout={"gm": 16, "nk": 1}),
    b=kt.In(32, 64, dtype="mx7b", layout={"gn": 8, "nk": 1}),
    y=kt.Out(64, 32),
):
    h = kt.buffer((64, 32), "f16", tile=(16, 8))
    for u in kt.par(1, on=kt.mg):
        acc = kt.zero(64, 32)
        for j in kt.range(2):
            av = kt.fill(a[0:64, j * 32 : j * 32 + 32])
            bv = kt.fill(b[0:32, j * 32 : j * 32 + 32])
            acc = kt.gemm(av, bv, acc)
        kt.drain(acc, h)
    for c in kt.par(2, on=kt.vc):
        for t in kt.range(8):
            r = c * 32 + t * 4
            kt.store(y[r : r + 4, :], kt.load(h[r : r + 4, :]))
